root=Path(__file__).resolve().parents[1]
site_config=json.loads((root/'config/site.json').read_text())
email=html.escape(site_config['supportEmail'])
publisher=html.escape(site_config['publisher'])
titles=l('Pikolumi: Color & Learn','Pikolumi: Colorie & Apprends','Pikolumi: Colorea y Aprende','Pikolumi: Colorir e Aprender','Pikolumi: لوّن وتعلّم')
subtitles=l('ABC, Math, Puzzles & Drawing','ABC, Maths, Puzzles & Dessin','ABC, mates, puzles y dibujos','ABC, contas e quebra-cabeças','حروف وحساب وألغاز ورسم')
play_titles=l('Pikolumi: Kids Learning Games','Pikolumi: Jeux éducatifs','Pikolumi: Juegos educativos','Pikolumi: Jogos educativos','Pikolumi: ألعاب تعليمية')
keywords=l('coloring,alphabet,letters,numbers,counting,arithmetic,shapes,memory,logic,mazes,rhythm,offline',
           'coloriage,alphabet,lettres,chiffres,compter,formes,mémoire,logique,labyrinthes,musique,hors ligne',
           'colorear,alfabeto,letras,números,contar,formas,memoria,lógica,laberintos,música,sin conexión',
           'colorir,alfabeto,letras,números,contagem,formas,memória,lógica,labirintos,música,offline',
           'تلوين,أرقام,ذاكرة,متاهة,ألوان,أشكال,كلمات,قراءة,إيقاع')
learning=l('Learn letters, words and handwriting in one language while the interface and questions use another. Each explorer can have a separate learning language.',
           'Apprends les lettres, les mots et l’écriture dans une langue, avec l’interface et les questions dans une autre. Chaque explorateur peut choisir sa langue d’apprentissage.',
           'Aprende letras, palabras y escritura en un idioma mientras la interfaz y las preguntas usan otro. Cada explorador puede tener su propio idioma de aprendizaje.',
           'Aprenda letras, palavras e escrita em um idioma, com a interface e as perguntas em outro. Cada explorador pode ter seu próprio idioma de aprendizagem.',
           'تعلّم الحروف والكلمات والكتابة بلغة، بينما تظهر الواجهة والأسئلة بلغة أخرى. يمكن لكل مستكشف اختيار لغة التعلّم الخاصة به.')
promo=l('360 coloring pages and 2,400 offline activities. Explore letters and words in five languages, with questions in your preferred language.',
        '360 coloriages et 2 400 activités hors ligne. Découvre lettres et mots dans cinq langues, avec les questions dans ta langue préférée.',
        '360 dibujos para colorear y 2.400 actividades sin conexión. Aprende letras y palabras en cinco idiomas con preguntas en el idioma que prefieras.',
        '360 desenhos para colorir e 2.400 atividades offline. Aprenda letras e palavras em cinco idiomas, com perguntas no idioma que você preferir.',
        '٣٦٠ صفحة تلوين و٢٤٠٠ نشاط دون إنترنت. تعلّم الحروف والكلمات بخمس لغات، مع الأسئلة باللغة التي تفضّلها.')
intro=l('Color, play and learn with Piko, your cheerful bird friend. Explore 16 sections and 2,400 offline activities, from first discoveries to creative challenges.','Colorie, joue et apprends avec Piko, ton joyeux ami oiseau. Explore 16 univers et 2 400 activités hors ligne, des premières découvertes aux défis créatifs.','Colorea, juega y aprende con Piko, tu alegre amigo pájaro. Explora 16 secciones y 2.400 actividades sin conexión, desde los primeros descubrimientos hasta los retos creativos.','Pinte, brinque e aprenda com Piko, seu alegre amigo passarinho. Explore 16 seções e 2.400 atividades sem internet, das primeiras descobertas aos desafios criativos.','لوّن والعب وتعلّم مع بيكو، صديقك الطائر المرح. استكشف ١٦ قسمًا و٢٤٠٠ نشاط دون إنترنت، من الاكتشافات الأولى إلى التحديات الإبداعية.')
short=l('Offline coloring, drawing, ABC, math and puzzles. 16 sections, 2,400 activities.','Coloriage, dessin, lettres, maths et puzzles hors ligne. 2 400 activités.','Colorear, dibujar, letras, mates y puzles sin conexión. 2.400 actividades.','Colorir, letras, matemática e quebra-cabeças offline. 2.400 atividades.','تلوين ورسم وحروف وحساب وألغاز دون إنترنت. ١٦ قسمًا و٢٤٠٠ نشاط.')
features=l('Fill pictures, paint with brushes, undo and redo, zoom in, or draw on a blank canvas. Keep each explorer’s artwork, favorites and progress separate on one device. All activities are available from the start. Stickers celebrate practice without locking content.','Remplis les dessins, utilise les pinceaux, annule, rétablis, zoome ou dessine sur une page blanche. Chaque explorateur garde ses dessins, favoris et progrès sur cet appareil. Toutes les activités sont disponibles dès le départ. Les autocollants encouragent la pratique sans bloquer le contenu.','Rellena dibujos, usa pinceles, deshaz y rehace, amplía o dibuja en un lienzo en blanco. Cada explorador guarda sus dibujos, favoritos y progreso por separado en este dispositivo. Todas las actividades están disponibles desde el principio. Las pegatinas celebran la práctica sin bloquear contenido.','Preencha desenhos, use pincéis, desfaça e refaça, amplie ou desenhe numa tela em branco. Cada explorador tem seus desenhos, favoritos e progresso separados neste aparelho. Todas as atividades estão disponíveis desde o início. Os adesivos celebram a prática sem bloquear conteúdo.','املأ الصور ولوّن بالفرشاة وتراجع وأعد وكبّر الصورة أو ارسم على لوحة فارغة. لكل مستكشف رسوماته ومفضلته وتقدمه على الجهاز نفسه. كل الأنشطة متاحة منذ البداية. تحتفي الملصقات بالتدريب دون قفل المحتوى.')
family=l('Recommended learning stages span ages 2–11, with advanced creative and puzzle challenges. Parents can adjust difficulty, language, sound and motion in a gated area. Five languages: English, French, Spanish, Brazilian Portuguese and Arabic, with essential spoken guidance bundled offline.','Les étapes conseillées couvrent les âges de 2 à 11 ans, avec des défis créatifs et des puzzles avancés. Les parents règlent la difficulté, la langue, les sons et les animations dans un espace protégé. Cinq langues : anglais, français, espagnol, portugais du Brésil et arabe, avec les consignes essentielles audio hors ligne.','Etapas recomendadas de 2 a 11 años, con retos creativos y puzles avanzados. Las familias ajustan dificultad, idioma, sonido y movimiento en una sección protegida. Cinco idiomas: inglés, francés, español, portugués de Brasil y árabe, con instrucciones esenciales habladas sin conexión.','Etapas recomendadas dos 2 aos 11 anos, com desafios criativos e quebra-cabeças avançados. Os pais ajustam dificuldade, idioma, som e movimento numa área protegida. Cinco idiomas: inglês, francês, espanhol, português do Brasil e árabe, com orientações essenciais faladas sem internet.','مراحل تعلم مقترحة للأعمار من سنتين إلى ١١ سنة، مع تحديات إبداعية وألغاز متقدمة. يضبط الوالدان الصعوبة واللغة والصوت والحركة في منطقة محمية. خمس لغات: الإنجليزية والفرنسية والإسبانية والبرتغالية البرازيلية والعربية، مع إرشادات صوتية أساسية مضمّنة دون إنترنت.')
monetization=l('Free, with banner and interstitial ads. No in-app purchases or subscriptions. Activities work offline; ads require a connection.','Gratuit, avec bannières et annonces interstitielles. Aucun achat intégré ni abonnement. Les activités fonctionnent hors ligne ; les annonces nécessitent une connexion.','Gratis, con anuncios de banner e intersticiales. Sin compras dentro de la app ni suscripciones. Las actividades funcionan sin conexión; los anuncios necesitan internet.','Grátis, com anúncios de banner e intersticiais. Sem compras no app nem assinaturas. As atividades funcionam sem internet; os anúncios precisam de conexão.','مجاني مع إعلانات شريطية وإعلانات بينية. لا مشتريات داخل التطبيق ولا اشتراكات. تعمل الأنشطة دون إنترنت، وتحتاج الإعلانات إلى اتصال.')
privacy=l('Profiles use avatars, without real names or birthdates. Artwork and learning progress are stored locally and are not uploaded by Pikolumi. Advertising is child-directed and non-personalized.','Les profils utilisent des avatars, sans vrais noms ni dates de naissance. Les dessins et la progression restent locaux et ne sont pas envoyés par Pikolumi. Les annonces sont adaptées aux enfants et non personnalisées.','Los perfiles usan avatares, sin nombres reales ni fechas de nacimiento. Pikolumi guarda los dibujos y el progreso localmente y no los sube a un servidor. La publicidad está dirigida a menores y no es personalizada.','Os perfis usam avatares, sem nomes reais nem datas de nascimento. Pikolumi guarda os desenhos e o progresso localmente, sem enviá-los a um servidor. A publicidade é infantil e não personalizada.','تستخدم الملفات صورًا رمزية دون أسماء حقيقية أو تواريخ ميلاد. تحفظ بيكولومي الرسومات والتقدم محليًا ولا ترفعهما إلى خادم. الإعلانات موجهة للأطفال وغير مخصصة.')
ad_data=l('Google Mobile Ads and its privacy SDK process IP addresses (which can indicate approximate location), app and ad interactions, advertising data, crash reports, performance data and diagnostics. App-scoped, SDK-instance or other device identifiers may also be processed for ad delivery, measurement and fraud prevention. Child-directed, non-personalized requests disable the Android advertising ID and Apple advertising identifier; this does not disable every SDK identifier or mean that no data is processed. Profiles, artwork and learning progress are not passed to Google. SDK data is encrypted in transit. Parents can open applicable Google privacy options in the protected parent area; the app does not request advertising consent from children.','Google Mobile Ads et son SDK de confidentialité traitent les adresses IP (qui peuvent indiquer une position approximative), les interactions avec l’application et les annonces, les données publicitaires, les rapports de plantage, les performances et les diagnostics. Des identifiants propres à l’application, à l’instance du SDK ou d’autres identifiants de l’appareil peuvent aussi être traités pour diffuser et mesurer les annonces et prévenir la fraude. Les requêtes destinées aux enfants et non personnalisées désactivent l’identifiant publicitaire Android et celui d’Apple ; cela ne désactive pas tous les identifiants du SDK et ne signifie pas qu’aucune donnée n’est traitée. Les profils, dessins et progrès ne sont pas transmis à Google. Les données du SDK sont chiffrées en transit. Les parents accèdent aux options Google applicables dans l’espace protégé ; l’application ne demande pas de consentement publicitaire aux enfants.','Google Mobile Ads y su SDK de privacidad procesan direcciones IP (que pueden indicar una ubicación aproximada), interacciones con la app y los anuncios, datos publicitarios, informes de fallos, rendimiento y diagnósticos. También pueden procesar identificadores de la app, de la instancia del SDK u otros identificadores del dispositivo para mostrar y medir anuncios y prevenir fraude. Las solicitudes infantiles no personalizadas desactivan el identificador publicitario de Android y el de Apple; esto no desactiva todos los identificadores del SDK ni significa que no se procesen datos. No se envían perfiles, dibujos ni progreso a Google. Los datos del SDK se cifran en tránsito. Las familias acceden a las opciones Google aplicables desde la sección protegida; la app no pide consentimiento publicitario a menores.','Google Mobile Ads e seu SDK de privacidade processam endereços IP (que podem indicar localização aproximada), interações com o app e anúncios, dados publicitários, relatórios de falhas, desempenho e diagnósticos. Identificadores do app, da instância do SDK ou outros identificadores do aparelho também podem ser processados para exibir e medir anúncios e prevenir fraudes. As solicitações infantis não personalizadas desativam o identificador de publicidade do Android e o da Apple; isso não desativa todos os identificadores do SDK nem significa ausência de tratamento de dados. Perfis, desenhos e progresso não são enviados ao Google. Os dados do SDK são criptografados em trânsito. Os pais acessam as opções Google aplicáveis na área protegida; o app não pede consentimento publicitário a crianças.','تعالج Google Mobile Ads وحزمة الخصوصية التابعة لها عناوين IP (التي قد تشير إلى موقع تقريبي)، والتفاعلات مع التطبيق والإعلانات، وبيانات الإعلانات، وتقارير الأعطال، وبيانات الأداء والتشخيص. وقد تعالج أيضًا معرّفات خاصة بالتطبيق أو بنسخة حزمة التطوير أو معرّفات أخرى للجهاز لعرض الإعلانات وقياسها ومنع الاحتيال. تعطّل الطلبات الموجهة للأطفال وغير المخصصة معرّف الإعلانات في Android ومعرّف الإعلانات في Apple؛ لكن ذلك لا يعطّل جميع معرّفات الحزمة ولا يعني عدم معالجة البيانات. لا تُرسل الملفات الشخصية أو الرسومات أو التقدم إلى Google. تُشفّر بيانات الحزمة أثناء النقل. يمكن للوالدين فتح خيارات خصوصية Google المتاحة في المنطقة المحمية؛ ولا يطلب التطبيق موافقة إعلانية من الأطفال.')
retention=l('Local saves remain until you remove the app or clear its data in device settings. Export is a parent action and opens the device share sheet; the parent chooses the destination. There is no cloud account, application backend, chat or app-owned analytics service.','Les données locales restent jusqu’à la suppression de l’application ou de ses données dans les réglages de l’appareil. L’export est réservé aux parents et ouvre le partage du système ; le parent choisit la destination. Aucun compte cloud, serveur applicatif, chat ou service d’analyse propre à l’application.','Los datos locales permanecen hasta eliminar la app o borrar sus datos en los ajustes del dispositivo. Exportar es una acción familiar que abre la hoja de compartir; el adulto elige el destino. No hay cuenta en la nube, servidor, chat ni servicio de analítica propio de la app.','Os dados locais ficam até remover o app ou limpar seus dados nas configurações do aparelho. A exportação é uma ação dos pais e abre o compartilhamento do sistema; o adulto escolhe o destino. Não há conta na nuvem, servidor, chat nem análise própria do app.','تبقى البيانات المحلية حتى إزالة التطبيق أو مسح بياناته في إعدادات الجهاز. التصدير إجراء للوالدين يفتح قائمة المشاركة ويختار الوالد وجهته. لا حساب سحابي ولا خادم للتطبيق ولا محادثة ولا خدمة تحليلات خاصة بالتطبيق.')
site=root/'site';site.mkdir(exist_ok=True);(site/'app-ads.txt').write_text('google.com, pub-3316613733634147, DIRECT, f08c47fec0942fa0\n')
listings=root/'docs/release/listings';listings.mkdir(parents=True,exist_ok=True)
for lang in LANGS:
 sections='\n'.join(f'- {name[lang]}: {count}' for _,count,_,_,name in SECTIONS)
 full='\n\n'.join([intro[lang],sections,features[lang],family[lang],learning[lang],monetization[lang],privacy[lang]])
 assert len(titles[lang])<=30 and len(subtitles[lang])<=30 and len(play_titles[lang])<=30 and len(short[lang])<=80,(lang,len(titles[lang]),len(subtitles[lang]),len(play_titles[lang]),len(short[lang]))
 assert len(keywords[lang].encode('utf-8'))<=100 and len(promo[lang])<=170 and len(full)<=4000,(lang,len(keywords[lang].encode('utf-8')),len(promo[lang]),len(full))
 listing={'status':'draft; release gates not yet met','supportURL':site_config['baseURL']+'/'+lang+'.html','privacyURL':site_config['baseURL']+'/'+lang+'.html#privacy','appleTitle':titles[lang],'appleSubtitle':subtitles[lang],'appleKeywords':keywords[lang],'applePromotionalText':promo[lang],'playTitle':play_titles[lang],'playShortDescription':short[lang],'description':full}
 (listings/f'{lang}.json').write_text(json.dumps(listing,ensure_ascii=False,indent=2)+'\n')
 text=lambda key:html.escape(UI[key][lang])
 direction='rtl' if lang=='ar' else 'ltr'
 links=' · '.join(f'<a href="{l}.html">{l.upper()}</a>' for l in LANGS)
 blocks=''.join(f'<p>{html.escape(p)}</p>' for p in [privacy[lang],ad_data[lang],retention[lang]])
 body=f'''<!doctype html><html lang="{lang}" dir="{direction}"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Pikolumi — {text('support')}</title><style>body{{margin:0;background:#fbf7ee;color:#344850;font:18px/1.65 system-ui,sans-serif}}main{{max-width:760px;margin:40px auto;padding:28px}}a{{color:#227780}}header{{background:#d6edf0;padding:28px;border-radius:28px}}h1{{font-size:38px;line-height:1.15}}section{{margin:35px 0}}small{{font-size:14px}}</style><main><nav>{links}</nav><header><h1>Pikolumi</h1><p>{html.escape(intro[lang])}</p></header><section><h2>{text('support')}</h2><p>{text('gateHelp')} {text('saved')}</p><p><a href="mailto:{email}?subject=Pikolumi">{email}</a></p></section><section id="privacy"><h2>{text('privacy')}</h2><small>2026-10-13 · {publisher}</small>{blocks}<p><a href="https://policies.google.com/privacy">Google Privacy Policy</a> · <a href="https://support.google.com/admob/answer/6128543">AdMob policies</a> · <a href="https://policies.google.com/technologies/retention">Google data retention</a></p><p>{html.escape(monetization[lang])}</p><p>{html.escape(UI['localPrivacy'][lang])}</p></section></main></html>'''
 (site/f'{lang}.html').write_text(body)
(site/'index.html').write_text((site/'en.html').read_text())
print('Five listing drafts and localized support/privacy pages generated with the confirmed support contact.')
